-- Restores the run check without affo_nav. A recorded REIT job would violate it:
-- delete or re-point those rows before rolling back.
ALTER TABLE "valuation_jobs" DROP CONSTRAINT "valuation_jobs_run_check";
ALTER TABLE "valuation_jobs" ADD CONSTRAINT "valuation_jobs_run_check" CHECK (("valuation_jobs"."valuation_run_id" is null) = ("valuation_jobs"."run_status" is null)
        and ("valuation_jobs"."run_status" is null or "valuation_jobs"."run_status" in ('computed', 'requires_review', 'rejected'))
        and ("valuation_jobs"."valuation_run_id" is not null) = ("valuation_jobs"."gap" is not null and "valuation_jobs"."gap"::text = 'run_recorded')
        and ("valuation_jobs"."valuation_run_id" is null or ("valuation_jobs"."method_status" = 'selected' and "valuation_jobs"."method" in ('fcff_base', 'normalized_fcff', 'excess_return', 'fcff_three_stage', 'revenue_margin_survival')))
        and ("valuation_jobs"."snapshot_gap" is null or "valuation_jobs"."gap"::text = 'snapshot_not_assembled')
        and ("valuation_jobs"."snapshot_gap" is null or "valuation_jobs"."snapshot_gap" in ('method_not_derived', 'security_missing', 'cost_of_capital_unavailable', 'normalization_unavailable', 'revenue_history_insufficient', 'revenue_history_non_positive', 'base_margin_unavailable', 'sales_to_capital_unavailable', 'tax_rate_unavailable', 'employee_equity_not_proposed', 'shares_outstanding_unavailable', 'market_unavailable', 'financial_base_unavailable', 'financial_base_stale', 'financial_declaration_missing', 'financial_filing_evidence_missing', 'growth_revenue_history_unavailable', 'growth_margin_unavailable', 'growth_tax_note_missing', 'growth_tax_jurisdictions_not_reconciled', 'growth_tax_pool_not_reconciled', 'reit_property_basis_unavailable', 'reit_affo_anchor_unavailable', 'reit_affo_filing_unavailable', 'reit_affo_reconciliation_missing', 'reit_affo_unaccepted', 'reit_nav_inputs_unavailable'))
        and ("valuation_jobs"."rule_version" = 'valuation-job-1.0.0' or "valuation_jobs"."gap" is null or "valuation_jobs"."gap"::text <> 'snapshot_not_assembled' or "valuation_jobs"."snapshot_gap" is not null)
        and ("valuation_jobs"."rule_version" <> 'valuation-job-1.0.0' or ("valuation_jobs"."snapshot_gap" is null and "valuation_jobs"."valuation_run_id" is null)));
